style.css:
@-moz-document domain("youtube.com") {
/* Background */
    body, #page-manager {
        background: url("https://i.pinimg.com/736x/42/e2/6a/42e26a114f9b352817b275dd8e3124bf.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Make main content slightly transparent so background shows */
    #content, #masthead-container, #container, #page-manager {
        background-color: rgba(0,0,0,0.7) !important;
    }

    /* Change video titles */
    #video-title {
        color: #e0e0e0 !important;
        font-family: "Cinzel Decorative", serif !important;
    }

    /* Change text colors */
    ytd-video-renderer, ytd-rich-grid-media, #primary, #secondary {
        color: #f0f0f0 !important;
    }
}
